players = []

def add_player(name):
    for p in players:
        if p["name"] == name:
            return False
    players.append({"name": name, "level": 1, "xp": 0})
    return True

def level_up(name):
    for p in players:
        if p["name"] == name:
            p["level"] += 1
            return p["level"]
    return None

